css:
.pond-report { font-family: "Inter", sans-serif; font-size: 11px; color: #12262B; }
.pond-report .hdr { display: flex; justify-content: space-between;
  align-items: flex-start; border-bottom: 2px solid #0B6E7F; padding-bottom: 8px; }
.pond-report .brand { font-size: 16px; font-weight: 700; color: #0B6E7F; }
.pond-report .sub { font-size: 11px; letter-spacing: .14em; text-transform: uppercase;
  color: #5E8188; }
.pond-report .meta { text-align: right; font-size: 10px; }
.pond-report h4 { margin: 14px 0 5px; font-size: 12px; font-weight: 700;
  border-bottom: 1px solid #D6DEDF; padding-bottom: 3px; }
.pond-report .note { color: #5E8188; font-weight: 400; font-size: 10px; }
.pond-report table { width: 100%; border-collapse: collapse; }
.pond-report .farmer td { padding: 3px 5px; border: 1px solid #D6DEDF; }
.pond-report .farmer .k { background: #F2F6F6; width: 15%; font-weight: 600; }
.pond-report .grid td, .pond-report .grid th { padding: 4px 6px;
  border-bottom: 1px solid #E6ECEC; }
.pond-report .grid thead th { background: #F2F6F6; font-weight: 600;
  border-bottom: 1px solid #D6DEDF; }
.pond-report .n { text-align: right; font-family: ui-monospace, monospace; }
.pond-report .b td { font-weight: 700; border-top: 1px solid #D6DEDF; }
.pond-report .hero { display: flex; justify-content: space-between;
  align-items: flex-end; background: #12262B; color: #EAEEEB;
  border-radius: 8px; padding: 12px 16px; margin: 10px 0; }
.pond-report .hero .lab { color: #7FC8CE; font-size: 9px; letter-spacing: .12em;
  text-transform: uppercase; }
.pond-report .hero .big { font-size: 24px; font-weight: 700;
  font-family: ui-monospace, monospace; }
.pond-report .hero .mid { font-size: 16px; font-weight: 600;
  font-family: ui-monospace, monospace; }
.pond-report .hero span { font-size: 11px; font-weight: 400; }
.pond-report .hero .right { text-align: right; }
.pond-report .sign { display: flex; justify-content: space-between;
  margin-top: 34px; font-size: 10px; color: #5E8188; }
